                _end(code, ["raise", type(exc).__qualname__, text])

        def _line(code, line):
            known = _codes.get(code)
            if known and line in _lines.get(known[0], ()):
                _hits.setdefault(known[0], set()).add(line)
            return _m.DISABLE

