    for key in sorted(set(left) | set(right)):
        old, new = left.get(key), right.get(key)
        if old is None or new is None:
            counts['unpaired'] += 1
            continue
        counts['paired'] += 1
        if not old['input'] or not new['input'] or old['output'] is None or new['output'] is None:
